import java.util.*;
import java.io.*;

public class Cutting{

    public static int[] stringToIntArray(String s){
        String[] parts = s.trim().split("\\s+");
        int[] result = new int[parts.length];
        for(int i=0; i<parts.length; i++){
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }

    boolean isSubArrayBalanced(int[] arr, int index){
        int evenCount = 0;
        int oddCount = 0;
        for(int i=0; i<=index; i++){
            if(arr[i] % 2 == 0) evenCount++;
            else oddCount++;
        }
        return evenCount == oddCount;
    }

    int findMinimumCostIndex(int[] arr, int coins, Map<Integer,Boolean> usedCuts){
        int minIndex = -1;
        int minCost = coins + 1;
        for(int i=1; i<arr.length - 1; i++){
            int cost = Math.abs(arr[i] - arr[i+1]);
            if(cost < minCost && isSubArrayBalanced(arr, i) && !usedCuts.containsKey(i)){
                minCost = cost;
                minIndex = i;
            }
        }
        return minIndex;
    }

    public int calculateMaxCuts(int total, int budget, int[] arr){
        int remainingCoins = budget;
        int cutsCount = 0;
        Map<Integer,Boolean> usedIndices = new HashMap<>();
        while(remainingCoins > 0){
            int index = findMinimumCostIndex(arr, remainingCoins, usedIndices);
            if(index >= 0){
                usedIndices.put(index, true);
                int cost = Math.abs(arr[index] - arr[index+1]);
                remainingCoins -= cost;
                cutsCount++;
            } else {
                break;
            }
        }
        return cutsCount;
    }

    public static void main(String[] args) throws Exception{
        Scanner sc = new Scanner(System.in);
        String line1 = sc.nextLine();
        String line2 = sc.nextLine();
        int[] nbArr = stringToIntArray(line1);
        int[] aArr = stringToIntArray(line2);
        Cutting c = new Cutting();
        int n = nbArr[0];
        int b = nbArr[1];
        int maxCuts = c.calculateMaxCuts(n, b, aArr);
        System.out.println(maxCuts);
        sc.close();
    }
}
